import android.text.Layout;
import android.text.Selection;
import android.text.Spannable;
import android.text.method.LinkMovementMethod;
import android.text.method.Touch;
import android.text.style.ClickableSpan;
import android.view.MotionEvent;
import android.view.ViewConfiguration;
import android.widget.TextView;

/**
 * Custom link movement method that properly defers link clicks until after
 * the long-press timeout. This prevents the link from being opened when the
 * user performs a long press (which should only open the context menu).
 */
public class LocalLinkMovementMethod extends LinkMovementMethod {
    static LocalLinkMovementMethod sInstance;

    public static LocalLinkMovementMethod getInstance() {
        if (sInstance == null)
            sInstance = new LocalLinkMovementMethod();

        return sInstance;
    }

    @Override
    public boolean onTouchEvent(TextView widget, Spannable buffer, MotionEvent event) {
        int action = event.getAction();

        if (action == MotionEvent.ACTION_UP ||
                action == MotionEvent.ACTION_DOWN) {
            int x = (int) event.getX();
            int y = (int) event.getY();

            x -= widget.getTotalPaddingLeft();
            y -= widget.getTotalPaddingTop();

            x += widget.getScrollX();
            y += widget.getScrollY();

            Layout layout = widget.getLayout();
            int line = layout.getLineForVertical(y);
            int off = layout.getOffsetForHorizontal(line, x);

            ClickableSpan[] link = buffer.getSpans(off, off, ClickableSpan.class);

            if (link.length != 0) {
                if (action == MotionEvent.ACTION_UP) {
                    // Defer link click until after the long-press timeout.
                    // This prevents the link from opening when the user
                    // long-presses (which should only show the context menu).
                    // Views with a registered OnLongClickListener will have
                    // their long press fire first; if one is registered,
                    // post the click with a delay equal to the long press timeout.
                    if (widget.hasOnLongClickListener()) {
                        final ClickableSpan clickableSpan = link[0];
                        widget.postDelayed(new Runnable() {
                            @Override
                            public void run() {
